struct Event {
    int l, r, id;
};

vector<int> choose(vector<Event>& a) {
    sort(a.begin(), a.end(), [](const Event& x, const Event& y) {
        return tie(x.r, x.l, x.id) < tie(y.r, y.l, y.id);
    });
    vector<int> ans;
    int last = -1;
    for (auto e : a) {
        if (e.l < last) continue;
        ans.push_back(e.id);
        last = e.r;
    }
    return ans;
}

